head.script:
scwin.onpageload = function() {


    // 여러 방법으로 project_id 파라미터 가져오기
    scwin.projectId = $p.getParameter("project_id");


    // URL에서 직접 파라미터 추출
    if (!scwin.projectId) {
        var urlParams = new URLSearchParams(window.location.search);
        scwin.projectId = urlParams.get('project_id');

    }

    // 부모 프레임에서 파라미터 가져오기
    if (!scwin.projectId) {
        try {
            var parentFrame = $p.parent();
            if (parentFrame && parentFrame.scwin && parentFrame.scwin.projectId) {
                scwin.projectId = parentFrame.scwin.projectId;

            }
        } catch(e) {

        }
    }

    // 기본값 설정
    if (!scwin.projectId) {
        scwin.projectId = "9";

    }



    // 프로젝트 데이터 로드
    scwin.loadProjectData();
};


// 프로젝트 데이터 로드
scwin.loadProjectData = function() {


    $.ajax({
        url: "/InsWebApp/ProjectUpdView.pwkjson",
        type: "POST",
        contentType: "application/x-www-form-urlencoded; charset=UTF-8",
        data: {
            project_id: scwin.projectId
        },
        success: function(res) {


            // 응답 데이터의 모든 키 확인
            if (res && typeof res === 'object') {

                for (var key in res) {

                }
            }

            // 응답 데이터 구조 확인 및 파싱
            var projectData = null;

            // projectVo 구조 확인 (가장 일반적인 구조)
            if (res && res.projectVo && (res.projectVo.projectId || res.projectVo.projectName)) {
                projectData = res.projectVo;

            }
            // 직접 프로젝트 데이터가 있는지 확인
            else if (res && (res.projectId || res.projectName)) {
                projectData = res;

            }
            // 데이터가 중첩된 구조인지 확인
            else if (res && res.data && (res.data.projectId || res.data.projectName)) {
                projectData = res.data;

            }
            // 배열 형태인지 확인
            else if (res && Array.isArray(res) && res.length > 0 && (res[0].projectId || res[0].projectName)) {
                projectData = res[0];

            }
            // 기타 가능한 구조들 확인
            else if (res && res.result && (res.result.projectId || res.result.projectName)) {
                projectData = res.result;

            }

            if (projectData) {

                scwin.setProjectData(projectData);
            } else {

                scwin.setDefaultData();
            }
        },
        error: function(xhr, status, error) {


            scwin.setDefaultData();
            alert("프로젝트 데이터 조회에 실패했습니다. 기본 데이터를 사용합니다.");
        }
    });
};

// 프로젝트 데이터 설정 함수
scwin.setProjectData = function(data) {


    try {
        // 데이터맵 객체 존재 확인 (여러 방법으로 시도)
        var dataMap = null;

        // 방법 1: 직접 접근
        if (typeof dm_projectDetail !== 'undefined') {
            dataMap = dm_projectDetail;

        }
        // 방법 2: $p.getComponentById로 접근
        else if (typeof $p !== 'undefined' && $p.getComponentById) {
            dataMap = $p.getComponentById("dm_projectDetail");

        }
        // 방법 3: window 객체에서 접근
        else if (typeof window.dm_projectDetail !== 'undefined') {
            dataMap = window.dm_projectDetail;

        }

        if (!dataMap) {

            return;
        }



        // 데이터맵에 데이터 설정
        dataMap.set("projectName", data.projectName || "");
        dataMap.set("teamLeader", data.userName || "");
        dataMap.set("teamLeaderEmail", data.userId || "");

        // 이메일 발송 시간 파싱 (HH:MM:SS 형식을 시간과 분으로 분리)
        var emailSendTime = data.emailSendTime || "";
        if (emailSendTime) {
            var timeParts = emailSendTime.split(":");
            var hour = timeParts[0] || "18";
            var minute = timeParts[1] || "00";

            dataMap.set("emailHour", hour);
            dataMap.set("emailMinute", minute);
            dataMap.set("emailSendTime", emailSendTime);

        } else {
            dataMap.set("emailHour", "18");
            dataMap.set("emailMinute", "00");
            dataMap.set("emailSendTime", "18:00:00");
        }

        // 이미지 설정
        var projectImageUrl = data.projectImageUrl;
        var finalImageUrl = null;

        if (projectImageUrl && projectImageUrl.trim() !== "" && projectImageUrl !== "null") {
            finalImageUrl = projectImageUrl;

        } else {
            // 기본 이미지 설정
            finalImageUrl = "https://collabee.s3.ap-northeast-2.amazonaws.com/projectImage/default_project_image.jpg";

        }

        dataMap.set("projectImage", finalImageUrl);



        // 데이터맵 강제 새로고침
        try {
            if (dataMap && dataMap.refresh) {
                dataMap.refresh();

            }
        } catch (refreshError) {

        }



        // 개별 컴포넌트 직접 업데이트
        try {
            // 프로젝트명 업데이트
            if (typeof input_projectName !== 'undefined') {
                input_projectName.setValue(data.projectName || "");

            }

            // 팀장 업데이트
            if (typeof input_teamLeader !== 'undefined') {
                input_teamLeader.setValue(data.userName || "");

            }

            // 시간 업데이트
            if (typeof input_emailHour !== 'undefined') {
                var timeParts = (data.emailSendTime || "18:00:00").split(":");
                input_emailHour.setValue(timeParts[0] || "18");

            }

            // 분 업데이트
            if (typeof input_emailMinute !== 'undefined') {
                var timeParts = (data.emailSendTime || "18:00:00").split(":");
                input_emailMinute.setValue(timeParts[1] || "00");

            }

            // 이미지 업데이트
            if (typeof img_projectImage !== 'undefined') {
                img_projectImage.setSrc(finalImageUrl);

            }

        } catch (componentError) {

        }

    } catch (error) {

    }
};

// 기본 데이터 설정 (DB 조회 실패 시에만 사용)
scwin.setDefaultData = function() {


    try {
        // 데이터맵 객체 존재 확인 (여러 방법으로 시도)
        var dataMap = null;

        // 방법 1: 직접 접근
        if (typeof dm_projectDetail !== 'undefined') {
            dataMap = dm_projectDetail;

        }
        // 방법 2: $p.getComponentById로 접근
        else if (typeof $p !== 'undefined' && $p.getComponentById) {
            dataMap = $p.getComponentById("dm_projectDetail");

        }
        // 방법 3: window 객체에서 접근
        else if (typeof window.dm_projectDetail !== 'undefined') {
            dataMap = window.dm_projectDetail;

        }

        if (!dataMap) {

            return;
        }

        dataMap.set("projectName", "프로젝트명 없음");
        dataMap.set("teamLeader", "");
        dataMap.set("teamLeaderEmail", "");
        dataMap.set("emailSendTime", "18:00:00");
        dataMap.set("emailHour", "18");
        dataMap.set("emailMinute", "00");

        // 기본 이미지 설정
        var defaultImageUrl = "https://collabee.s3.ap-northeast-2.amazonaws.com/projectImage/default_project_image.jpg";
        dataMap.set("projectImage", defaultImageUrl);


    } catch (error) {

    }
};

// 프로젝트 이미지 변경
scwin.btn_changeImage_onclick = function(e) {


    // 파일 선택 input 생성
    var fileInput = document.createElement('input');
    fileInput.type = 'file';
    fileInput.accept = 'image/*';
    fileInput.style.display = 'none';
    document.body.appendChild(fileInput);

    // 파일 선택 이벤트 리스너
    fileInput.addEventListener('change', function(event) {
        var file = event.target.files[0];
        if (file) {


            // 파일 크기 체크 (10MB 제한)
            if (file.size > 10 * 1024 * 1024) {
                alert("파일 크기가 10MB를 초과합니다. 더 작은 파일을 선택해주세요.");
                document.body.removeChild(fileInput);
                return;
            }

            // 파일 타입 체크
            if (!file.type.startsWith('image/')) {
                alert("이미지 파일만 업로드할 수 있습니다.");
                document.body.removeChild(fileInput);
                return;
            }

            // 이미지 미리보기 설정
            var reader = new FileReader();
            reader.onload = function(e) {
                var imageUrl = e.target.result;

                // 이미지 즉시 표시
                if (typeof img_projectImage !== 'undefined') {
                    img_projectImage.setSrc(imageUrl);
                }


            };
            reader.readAsDataURL(file);

            // 서버에 파일 업로드
            scwin.uploadProjectImage(file);
        }

        // 파일 input 제거
        document.body.removeChild(fileInput);
    });

    // 파일 선택 다이얼로그 열기
    fileInput.click();
};

// 프로젝트 이미지 업로드 함수
scwin.uploadProjectImage = function(file) {


    var formData = new FormData();
    formData.append('file', file);
    formData.append('projectId', scwin.projectId);

    // 업로드 중 표시
    var uploadingMessage = "이미지 업로드 중...";


    $.ajax({
        url: '/InsWebApp/uploadProjectImage.pwkjson',
        type: 'POST',
        data: formData,
        processData: false,
        contentType: false,
        success: function(response) {


            // 응답 객체의 모든 속성 확인
            if (response && typeof response === 'object') {

                for (var key in response) {
                    if (response.hasOwnProperty(key)) {

                    }
                }
            }

            // 응답이 문자열인 경우 JSON 파싱 시도
            if (typeof response === 'string') {
                try {
                    response = JSON.parse(response);

                } catch (e) {

                }
            }

            // 성공 여부 확인 (여러 가지 방법으로 확인)
            var isSuccess = false;
            var imageUrl = null;
            var message = null;

            if (response) {
                // WebSquare 응답 형식 확인 (elHeader가 있는 경우)
                if (response.elHeader) {
                    // WebSquare 응답에서 성공 여부 확인
                    if (response.elHeader.resSuc === true) {
                        isSuccess = true;
                        imageUrl = response.imageUrl;
                        message = response.message;
                    } else {
                        // WebSquare 오류 메시지
                        message = response.elHeader.resMsg || "WebSquare 오류가 발생했습니다.";
                    }
                }
                // 직접 success 속성 확인
                else if (response.success === true) {
                    isSuccess = true;
                    imageUrl = response.imageUrl;
                    message = response.message;
                }
                // 일반 JSON 응답 형식
                else if (response.resultCode === 'success' || response.status === 'success') {
                    isSuccess = true;
                    imageUrl = response.imageUrl || response.data || response.url;
                }
                // 에러 메시지가 없다면 성공으로 간주
                else if (!response.error && !response.message && response.imageUrl) {
                    isSuccess = true;
                    imageUrl = response.imageUrl;
                }
            }



            if (isSuccess && imageUrl) {


                // 데이터맵 업데이트
                if (typeof dm_projectDetail !== 'undefined') {
                    dm_projectDetail.set("projectImage", imageUrl);
                }

                // 이미지 표시
                if (typeof img_projectImage !== 'undefined') {
                    img_projectImage.setSrc(imageUrl);
                }

                // 모달 이미지도 업데이트
                if (typeof img_modalProjectImage !== 'undefined') {
                    img_modalProjectImage.setSrc(imageUrl);
                }

                alert("프로젝트 이미지가 성공적으로 업로드되었습니다!");

            } else {

                var errorMessage = message || "알 수 없는 오류가 발생했습니다.";
                alert("이미지 업로드에 실패했습니다: " + errorMessage);
            }
        },
        error: function(xhr, status, error) {

            alert("이미지 업로드 중 오류가 발생했습니다. 다시 시도해주세요.");
        }
    });
};

// 저장 버튼 클릭
scwin.btn_save_onclick = function(e) {


    // 입력 필드에서 직접 현재 값 가져오기
    var projectName = input_projectName.getValue() || dm_projectDetail.get("projectName");
    var emailHour = input_emailHour.getValue() || dm_projectDetail.get("emailHour");
    var emailMinute = input_emailMinute.getValue() || dm_projectDetail.get("emailMinute");


    // 유효성 검사
    if (!projectName || projectName.trim() === "") {
        alert("프로젝트명을 입력해주세요.");
        return;
    }

    if (!emailHour || emailHour.trim() === "") {
        alert("메일 발송 시간을 입력해주세요.");
        return;
    }

    if (!emailMinute || emailMinute.trim() === "") {
        alert("메일 발송 분을 입력해주세요.");
        return;
    }

    // 시간 유효성 검사
    var hour = parseInt(emailHour);
    var minute = parseInt(emailMinute);

    if (isNaN(hour) || hour < 0 || hour > 23) {
        alert("시간은 0~23 사이의 숫자를 입력해주세요.");
        return;
    }

    if (isNaN(minute) || minute < 0 || minute > 59) {
        alert("분은 0~59 사이의 숫자를 입력해주세요.");
        return;
    }

    // 시간 합치기
    var emailSendTime = String(hour).padStart(2, '0') + ":" + String(minute).padStart(2, '0') + ":00";



    // 서버에 프로젝트 정보 업데이트 요청


    $.ajax({
        url: "/InsWebApp/ProjectUpd.pwkjson",
        type: "POST",
        contentType: "application/x-www-form-urlencoded; charset=UTF-8",
        data: {
            projectId: scwin.projectId,
            projectName: projectName,
            emailSendTime: emailSendTime
        },
        beforeSend: function(xhr) {

        },
        success: function(response) {


            // WebSquare 응답 처리 (void 반환 타입에 대한 특별 처리)
            var isSuccess = false;
            var message = "프로젝트 설정이 저장되었습니다.";



            if (response) {
                // WebSquare elHeader 확인
                if (response.elHeader) {

                    if (response.elHeader.resSuc === true) {
                        isSuccess = true;

                        // 서버에서 받은 메시지가 있으면 사용
                        if (response.success === true && response.message) {
                            message = response.message;
                        }
                    } else if (response.elHeader.resSuc === false) {
                        isSuccess = false;
                        message = response.elHeader.resMsg || "서버 오류가 발생했습니다.";

                    } else {
                        // resSuc이 정의되지 않은 경우, 직접 success 확인
                        if (response.success === true) {
                            isSuccess = true;
                            message = response.message || message;

                        } else {
                            isSuccess = true;

                        }
                    }
                } else {
                    // elHeader가 없는 경우 직접 success 확인
                    if (response.success === true) {
                        isSuccess = true;
                        message = response.message || message;

                    } else {
                        isSuccess = true;

                    }
                }
            } else {
                // 응답이 전혀 없는 경우
                isSuccess = true;

            }



            if (isSuccess) {
                alert(message);


                // 업데이트 성공 후 최신 데이터 다시 로드
                setTimeout(function() {

                    scwin.loadProjectData();
                }, 500);
            } else {
                alert("저장 중 오류가 발생했습니다: " + message);

            }
        },
        error: function(xhr, status, error) {

            alert("프로젝트 정보 저장 중 오류가 발생했습니다. 다시 시도해주세요.");
        }
    });

};

// 프로젝트 삭제
scwin.btn_deleteProject_onclick = function(e) {


    // 삭제 확인 모달 열기
    scwin.openDeleteConfirmModal();
};

// 삭제 확인 모달 열기
scwin.openDeleteConfirmModal = function() {
    // 모달 배경 표시 (모달창도 함께 표시됨)
    grp_modalBackground.setStyle("display", "flex");

    // 입력 필드 초기화
    input_confirmProjectName.setValue("");

    // 현재 프로젝트명 표시 업데이트
    try {
        var currentProjectName = dm_projectDetail.get("projectName");
        if (typeof output_modalProjectName !== 'undefined' && currentProjectName) {
            output_modalProjectName.setValue(currentProjectName);
        }
    } catch (error) {

    }

    // 모달에 현재 프로젝트 이미지 표시
    var currentImageUrl = null;

    try {
        // 데이터맵에서 현재 이미지 URL 가져오기
        if (typeof dm_projectDetail !== 'undefined') {
            currentImageUrl = dm_projectDetail.get("projectImage");
        }

        // 데이터맵에서 가져오지 못한 경우 img_projectImage에서 직접 가져오기
        if (!currentImageUrl && typeof img_projectImage !== 'undefined') {
            currentImageUrl = img_projectImage.getSrc();
        }

        // 여전히 없다면 기본 이미지 URL 사용
        if (!currentImageUrl || currentImageUrl === "" || currentImageUrl === "null") {
            currentImageUrl = "https://collabee.s3.ap-northeast-2.amazonaws.com/projectImage/default_project_image.jpg";
        }



        // 모달 이미지 설정
        if (typeof img_modalProjectImage !== 'undefined') {
            img_modalProjectImage.setSrc(currentImageUrl);

        }

    } catch (error) {


        // 오류 발생 시 기본 이미지 설정
        if (typeof img_modalProjectImage !== 'undefined') {
            img_modalProjectImage.setSrc("https://collabee.s3.ap-northeast-2.amazonaws.com/projectImage/default_project_image.jpg");
        }
    }


};

// 삭제 확인 모달 닫기
scwin.closeDeleteConfirmModal = function() {
    grp_modalBackground.setStyle("display", "none");


};

// 모달 배경 클릭 시 닫기
scwin.grp_modalBackground_onclick = function(e) {
    // 모달창 외부 영역 클릭 시만 닫기
    if (e.target === grp_modalBackground.getElement()) {
        scwin.closeDeleteConfirmModal();
    }
};

// 모달창 내부 클릭 시 이벤트 전파 방지
scwin.grp_deleteModal_onclick = function(e) {
    // 이벤트 전파 중지 (모달창 내부 클릭 시 닫히지 않도록)
    e.stopPropagation();
};

// 모달 취소 버튼
scwin.btn_modalCancel_onclick = function(e) {
    scwin.closeDeleteConfirmModal();
};

// 모달 X 버튼
scwin.btn_modalClose_onclick = function(e) {
    scwin.closeDeleteConfirmModal();
};

// 모달 확인 버튼 (실제 삭제 실행)
scwin.btn_modalConfirm_onclick = function(e) {


    var originalProjectName = dm_projectDetail.get("projectName");
    var inputProjectName = input_confirmProjectName.getValue();



    // 프로젝트명 검증
    if (!inputProjectName || inputProjectName.trim() === "") {
        alert("프로젝트명을 입력해주세요.");
        return;
    }

    if (inputProjectName.trim() !== originalProjectName.trim()) {
        alert("프로젝트명이 일치하지 않습니다.\n정확한 프로젝트명을 입력해주세요.");
        return;
    }

    // 프로젝트명이 일치하면 삭제 진행
    scwin.executeProjectDelete(originalProjectName);
};

// 실제 프로젝트 삭제 실행
scwin.executeProjectDelete = function(projectName) {


    // 모달 닫기
    scwin.closeDeleteConfirmModal();

    // 삭제 완료 메시지
    alert("'" + projectName + "' 프로젝트가 삭제되었습니다.\n메인 페이지로 이동합니다.");

    // 실제로는 서버에 삭제 요청 후 메인 페이지로 이동


    // 부모 창으로 대시보드 이동
    try {
        var parentFrame = $p.parent();
        if (parentFrame && parentFrame.scwin && parentFrame.scwin.changeMenu) {
            parentFrame.scwin.changeMenu("dashboard");
        }
    } catch(e) {

    }
};

// X 버튼 클릭 (프로젝트 페이지로 돌아가기)
scwin.btn_close_onclick = function(e) {


    // 변경사항 확인 (실제로는 폼 데이터 변경 여부 체크)
    if (confirm("설정 페이지를 닫고 프로젝트 페이지로 돌아가시겠습니까?")) {
        try {
            // 부모 창의 메뉴 변경 함수 호출하여 프로젝트 페이지로 이동
            var parentFrame = $p.parent();
            if (parentFrame && parentFrame.scwin && parentFrame.scwin.changeMenu) {
                parentFrame.scwin.changeMenu("project1"); // 또는 현재 프로젝트에 맞는 메뉴
            }
        } catch(e) {

        }
    }
};
